window.TAD_RULINGS = {
 "naranjo_v_spectrum_s279397": {
  "cite": "Naranjo v. Spectrum Security Services, Inc. (Cal. May 6, 2024, S279397)",
  "court": "California Supreme Court",
  "date": "2024-05-06",
  "docket": "S279397",
  "excerpt": "Under long established law, an employer cannot incur civil or criminal penalties for the willful nonpayment of wages when the employer reasonably and in good faith disputes that wages are due.",
  "holding": "We hold that an employer’s objectively reasonable, good faith belief that it has provided employees with adequate wage statements precludes an award of penalties under section 226, subdivision (e)(1).",
  "disposition": "The judgment of the Court of Appeal is affirmed.",
  "source": "HFforLegal/case-law, CC BY 4.0",
  "real": true
 }
};
